pub fn rq(verb: u8, plan: bool, queued: u64) -> GolReq {
    return GolReq { verb: verb, plan: plan, queued: queued, issue: 11275, scratch: "/tmp/s", t27b: "t27b", t27c: "t27c", tri: "/tmp/tri" };
}

pub fn argv_is(r: GolReq, ev: &'static str, k: u8, n: u64, want: &'static str, buf: &mut [u8], wo: &mut [u8], wp: &mut [usize]) -> bool {
    let m: usize = step_argv(r, ev, k, n, buf, wo, wp);
    return ((m > 0) && buf_is(buf, m, want));
}

pub fn name_is(ev: &'static str, i: usize, want: &'static str) -> bool {
    return span_is(ev, q_start(ev, i), line_end(ev, q_start(ev, i)), want);
}

pub fn buf_has_not(buf: &[u8], n: usize, want: &'static str) -> bool {
    let mut at: usize = 0;
    while ((at + want.len()) <= n) {
        let mut k: usize = 0;
        while ((k < want.len()) && (buf[((at + k)) as usize] == want.as_bytes()[(k) as usize])) {
            k = (k + 1);
        }
        if (k == want.len()) {
            return false;
        }
        at = (at + 1);
    }
    return true;
}

