pub const EDIT_APPEND: u8 = 2;

pub const EDIT_LINES: u8 = 1;

pub const EDIT_WHOLE: u8 = 0;

pub fn edits_meet(a_kind: u8, a_start: u32, a_end: u32, b_kind: u8, b_start: u32, b_end: u32) -> bool {
    if ((a_kind == EDIT_APPEND) && (b_kind == EDIT_APPEND)) {
        return false;
    }
    if (a_kind != EDIT_LINES) {
        return true;
    }
    if (b_kind != EDIT_LINES) {
        return true;
    }
    if (a_start >= a_end) {
        return true;
    }
    if (b_start >= b_end) {
        return true;
    }
    return ((a_start <= b_end) && (b_start <= a_end));
}

